</div><script>
document.querySelectorAll('.pa-detail-form').forEach((form) => {
    const list = form.querySelector('[data-highlight-list]');
    const template = form.querySelector('[data-highlight-template]');
    const orderList = form.querySelector('[data-detail-order-list]');
    const orderInput = form.querySelector('[data-detail-order]');

    const syncHighlights = () => {
        const rows = Array.from(list.querySelectorAll('.pa-highlight-row'));
        rows.forEach((row, index) => {
            row.querySelectorAll('[name], [data-field]').forEach((field) => {
                const key = field.dataset.field || field.name.match(/\]\[([^\]]+)\]$/)?.[1];
                if (key) field.name = `highlights[${index}][${key}]`;
            });
            row.querySelector('[data-remove-highlight]').disabled = rows.length <= 9;
        });
        form.querySelector('[data-add-highlight]').disabled = rows.length >= 30;
    };

    form.querySelector('[data-add-highlight]').addEventListener('click', () => {
        if (list.querySelectorAll('.pa-highlight-row').length >= 30) return;
        list.append(template.content.cloneNode(true));
        syncHighlights();
    });

    list.addEventListener('click', (event) => {
        const removeButton = event.target.closest('[data-remove-highlight]');
        if (!removeButton || list.querySelectorAll('.pa-highlight-row').length <= 9) return;
        removeButton.closest('.pa-highlight-row').remove();
        syncHighlights();
    });

    orderList.addEventListener('click', (event) => {
        const moveButton = event.target.closest('[data-order-move]');
        if (!moveButton) return;
        const row = moveButton.closest('li');
        const direction = Number(moveButton.dataset.orderMove);
        const neighbor = direction < 0 ? row.previousElementSibling : row.nextElementSibling;
        if (!neighbor) return;
        if (direction < 0) orderList.insertBefore(row, neighbor);
        else orderList.insertBefore(neighbor, row);
        orderInput.value = Array.from(orderList.children, (item) => item.dataset.sectionOrder).join(',');
    });

    syncHighlights();
});
</script></body></html>
